from __future__ import annotations
import math

def exact_defect(weights: list[float], ceiling: int) -> dict[str, float]:
    tails = [q ** (ceiling + 1) for q in weights]
    completed = math.prod(1.0 / (1.0 - q) for q in weights)
    normalized = 1.0 - math.prod(1.0 - a for a in tails)
    return {"completed": completed, "defect": completed * normalized,
            "upper_bound": completed * math.fsum(tails)}

from __future__ import annotations
import math

def sieve(limit: int) -> list[int]:
    mark = [True] * limit
    if limit > 0: mark[0] = False
    if limit > 1: mark[1] = False
    for p in range(2, math.isqrt(limit - 1) + 1):
        if mark[p]:
            for multiple in range(p * p, limit, p): mark[multiple] = False
    return [p for p in range(limit) if mark[p]]

def prime_error_terms(limit: int, beta: float, ceiling: int) -> tuple[float, float]:
    weights = [p ** (-beta) for p in sieve(limit)]
    completed = math.prod(1 / (1 - q) for q in weights)
    return completed, completed * math.fsum(q ** (ceiling + 1) for q in weights)

